class Node:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def insert(node, value):
    if node is None:
        return Node(value)
    if value < node.value:
        node.left = insert(node.left, value)
    elif value > node.value:
        node.right = insert(node.right, value)
    return node


def build(values):
    root = None
    for v in values:
        root = insert(root, v)
    return root


root = build([6, 2, 9, 1, 4, 7])
print(root.left.right.value)
print(root.right.left.value, root.right.right)
node, steps = root, 0
while node.left:
    node = node.left
    steps += 1
print(node.value, steps)
